<?php
return function(Router $r){
    $r->get('/web-admin/cloud',function(){
        $info=HubClientService::info();$overview=null;$error='';if($info)try{$overview=HubClientService::request('GET','/api/v1/overview');}catch(Throwable $e){$error=$e->getMessage();}
        $once=$_SESSION['hub_one_time'] ?? null;unset($_SESSION['hub_one_time']);if(!is_array($once)||($once['expires_at']??0)<time())$once=null;
        return View::render(__DIR__.'/views/cloud.php',['title'=>'Cloud Gateway · Admin Studio','info'=>$info,'overview'=>$overview,'error'=>$error,'once'=>$once]);
    });
    $r->post('/web-admin/cloud/login',function(){
        $password=$_POST['password']??'';$operator=$_POST['operator_token']??'';if(!is_string($password)||!is_string($operator)||strlen($password)>4096||strlen($operator)>4096)throw new InvalidArgumentException('Enter valid Hub credentials.');
        HubClientService::login(text_input('gateway_url',2048),text_input('username',120,false),$password,$operator);return redirect('/web-admin/cloud','Connected to the cloud Gateway.');
    });
    $r->post('/web-admin/cloud/disconnect',function(){try{HubClientService::request('POST','/api/v1/logout');}finally{HubClientService::disconnect();}return redirect('/web-admin/cloud','Hub session cleared.');});
    $r->post('/web-admin/cloud/clients',function(){HubClientService::request('POST','/api/v1/clients',['name'=>text_input('name',120)]);return redirect('/web-admin/cloud','Client created in your cloud Gateway.');});
    $r->post('/web-admin/cloud/sites',function(){
        try{$manifest=json_decode(text_input('manifest',100000),true,48,JSON_THROW_ON_ERROR);}catch(JsonException){throw new InvalidArgumentException('Enter valid manifest JSON.');}if(!is_array($manifest))throw new InvalidArgumentException('Enter a manifest object.');
        $result=HubClientService::request('POST','/api/v1/sites',['name'=>text_input('name',120),'client_id'=>text_input('client_id',64),'url'=>text_input('url',2048,false),'render_mode'=>text_input('render_mode',20),'webhook_url'=>text_input('webhook_url',2048,false),'deploy_hook_url'=>text_input('deploy_hook_url',2048,false),'domain_expires'=>text_input('domain_expires',10,false),'manifest'=>$manifest]);
        $_SESSION['hub_one_time']=['kind'=>'site','result'=>$result,'expires_at'=>time()+300];return redirect('/web-admin/cloud','Site registered. Copy its connector credentials from the one-time notice.');
    });
    $r->post('/web-admin/cloud/users',function(){
        $sites=$_POST['sites']??[];if(!is_array($sites)||count($sites)>30||count(array_filter($sites,'is_string'))!==count($sites))throw new InvalidArgumentException('Choose assigned sites.');$result=HubClientService::request('POST','/api/v1/users',['username'=>text_input('username',120),'client_id'=>text_input('client_id',64),'role'=>text_input('role',30),'sites'=>array_values($sites)]);$_SESSION['hub_one_time']=['kind'=>'user','result'=>$result,'expires_at'=>time()+300];return redirect('/web-admin/cloud','Client account provisioned. Copy its generated password from the one-time notice.');
    });
    $r->post('/web-admin/cloud/users/disable',function(){HubClientService::request('POST','/api/v1/users/disable',['username'=>text_input('username',120)]);return redirect('/web-admin/cloud','Client account disabled and active sessions revoked.');});
    $r->get('/web-admin/cloud/site/{site}',function($p){
        $site=$p['site'];if(!preg_match('/^site_[a-f0-9]{16}$/D',$site))throw new InvalidArgumentException('Choose a registered cloud site.');$overview=HubClientService::request('GET','/api/v1/overview');$profile=null;foreach($overview['sites'] as $item)if($item['id']===$site)$profile=$item;if(!$profile)throw new InvalidArgumentException('Site access is unavailable.');$manifest=HubClientService::request('GET','/api/v1/sites/'.$site.'/manifest');$slug=$_GET['page']??($manifest['pages'][0]['slug']??'');if(!is_string($slug)||($slug!==''&&!preg_match('/^[a-z][a-z0-9_-]{0,63}$/D',$slug)))throw new InvalidArgumentException('Choose a manifest page.');$definition=null;foreach($manifest['pages']??[] as $item)if($item['slug']===$slug)$definition=$item;$page=$definition?HubClientService::request('GET','/api/v1/sites/'.$site.'/pages/'.$slug):null;$versions=$page?HubClientService::request('GET','/api/v1/sites/'.$site.'/pages/'.$slug.'/versions')['versions']:[];
        return View::render(__DIR__.'/views/cloud-site.php',['title'=>$profile['name'].' · Cloud Studio','info'=>HubClientService::info(),'site'=>$profile,'manifest'=>$manifest,'definition'=>$definition,'page'=>$page,'versions'=>$versions,'jobs'=>HubClientService::request('GET','/api/v1/sites/'.$site.'/deployments')['deployments'],'media'=>HubClientService::request('GET','/api/v1/sites/'.$site.'/media')['media'],'audit'=>HubClientService::request('GET','/api/v1/sites/'.$site.'/audit')['audit'],'health'=>HubClientService::request('GET','/api/v1/sites/'.$site.'/health')]);
    });
    $r->post('/web-admin/cloud/site/{site}/save',function($p){
        $site=$p['site'];$slug=text_input('page',64);if(!preg_match('/^site_[a-f0-9]{16}$/D',$site)||!preg_match('/^[a-z][a-z0-9_-]{0,63}$/D',$slug))throw new InvalidArgumentException('Choose a valid site and page.');$manifest=HubClientService::request('GET','/api/v1/sites/'.$site.'/manifest');$definition=null;foreach($manifest['pages']??[] as $item)if($item['slug']===$slug)$definition=$item;if(!$definition)throw new InvalidArgumentException('Page not declared by this site.');$input=$_POST['fields']??[];if(!is_array($input)||array_diff(array_keys($input),array_column($definition['fields'],'key')))throw new InvalidArgumentException('Enter valid manifest fields.');$fields=[];foreach($definition['fields'] as $field){$value=$input[$field['key']]??'';if(!is_string($value))throw new InvalidArgumentException('Enter valid field values.');if($field['type']==='boolean')$value=$value==='1';elseif($field['type']==='number'){if($value==='')$value=null;elseif(!preg_match('/^-?\d{1,13}(?:\.\d{1,8})?$/D',$value))throw new InvalidArgumentException('Enter a valid number.');else $value=(float)$value;}$fields[$field['key']]=$value;}HubClientService::request('PUT','/api/v1/sites/'.$site.'/pages/'.$slug,['version'=>int_range($_POST['version']??'',0,PHP_INT_MAX),'fields'=>$fields]);return redirect('/web-admin/cloud/site/'.$site.'?page='.$slug,'Draft saved to the cloud. Live content is unchanged until publishing.');
    });
    $r->post('/web-admin/cloud/site/{site}/publish',function($p){$site=$p['site'];$slug=text_input('page',64);$result=HubClientService::request('POST','/api/v1/sites/'.$site.'/pages/'.$slug.'/publish',['version'=>int_range($_POST['version']??'',0,PHP_INT_MAX)]);return redirect('/web-admin/cloud/site/'.$site.'?page='.$slug.'#hub-deliveries','Published content saved. Delivery queued; live status requires site confirmation.');});
    $r->post('/web-admin/cloud/site/{site}/rollback',function($p){$site=$p['site'];$slug=text_input('page',64);HubClientService::request('POST','/api/v1/sites/'.$site.'/pages/'.$slug.'/rollback',['version'=>int_range($_POST['version']??'',0,PHP_INT_MAX),'target_version'=>int_range($_POST['target_version']??'',0,PHP_INT_MAX)]);return redirect('/web-admin/cloud/site/'.$site.'?page='.$slug.'#hub-deliveries','Rollback published as a new version. Delivery queued.');});
    $r->post('/web-admin/cloud/site/{site}/media',function($p){$file=$_FILES['file']??null;if(!is_array($file))throw new InvalidArgumentException('Choose a media file.');HubClientService::upload($p['site'],$file);return redirect('/web-admin/cloud/site/'.$p['site'].'#hub-media','File uploaded to the cloud media library.');});
    $r->post('/web-admin/cloud/site/{site}/health',function($p){HubClientService::request('POST','/api/v1/sites/'.$p['site'].'/health');return redirect('/web-admin/cloud/site/'.$p['site'].'#hub-health','A real site health check was recorded.');});
};
